const res = $input.first().json || {};
const updates = Array.isArray(res.result) ? res.result : [];
if (!updates.length) return [];
let max = 0;
for (const u of updates) if (u.update_id > max) max = u.update_id;
return [{ json: { next_offset: max + 1 } }];

const res = $input.first().json || {};
const updates = Array.isArray(res.result) ? res.result : [];
const tradingRe = /\b(spreads?|swaps?|swap-free|margin|leverage|lots?|deposit\w*|withdraw\w*|fund\w*|balance|account types?|standard|raw spread|zero|pro account|mt4|mt5|metatrader|platform|stop ?out|trad(e|es|ing)|scalp\w*|kyc|verif\w*|pips?|gold|xauusd|eurusd|nfp|cpi|fomc|news)\b/i;
const ibRe = /\b(ib|introducing broker|referr\w*|refer|affiliate\w*|partner\w*|rebates?|sub-?accounts?|traffic|sign-?ups?|downline|network|leads?|cpa|revenue share|my clients|milestone)\b/i;
const out = [];
for (const u of updates) {
  const m = u.message;
  if (!m || typeof m.text !== 'string' || !m.chat) continue;
  const text = m.text.trim();
  const t = tradingRe.test(text);
  const i = ibRe.test(text);
  const track = t && i ? 'MIXED' : (i ? 'IB' : (t ? 'TRADING' : 'GENERAL'));
  out.push({ json: {
    update_id: u.update_id,
    chat_id: String(m.chat.id),
    first_name: (m.from && m.from.first_name) || 'there',
    text,
    track,
    reply_to_text: (m.reply_to_message && m.reply_to_message.text) || '',
    received_at: new Date((m.date || 0) * 1000).toISOString()
  }});
}
return out;

const STAFF_CHAT_IDS = ['YOUR_STAFF_CHAT_ID'];
const p = $('Parse Messages').item.json;
const c = $input.item.json || {};
const crm = {
  registered: c.registered === true,
  kyc_verified: c.kyc_verified === true,
  ftd_amount: Number(c.ftd_amount || 0),
  balance: Number(c.balance || 0),
  days_inactive: Number(c.days_inactive || 0),
  is_ib: c.is_ib === true,
  ib_referrals: Number(c.ib_referrals || 0),
  ib_link: c.ib_link || '',
  one_on_one_booked: c.one_on_one_booked === true,
  escalated: c.escalated === true,
  escalation_reason: c.escalation_reason || '',
  last_staff_note: c.last_staff_note || ''
};

let staff = null;
if (STAFF_CHAT_IDS.includes(p.chat_id)) {
  const replyCmd = p.text.match(/^\/reply\s+(-?\d+)\s+([\s\S]+)/i);
  const resumeCmd = p.text.match(/^\/resume(?:\s+(-?\d+))?\s*$/i);
  const alertTarget = (p.reply_to_text.match(/Telegram (-?\d+)/) || [])[1];
  if (replyCmd) staff = { target_chat_id: replyCmd[1], staff_text: replyCmd[2].trim() };
  else if (resumeCmd) staff = { target_chat_id: resumeCmd[1] || p.chat_id, staff_text: '' };
  else if (alertTarget && !p.text.startsWith('/')) staff = { target_chat_id: alertTarget, staff_text: p.text };
}
if (staff) {
  return { json: { ...p, crm, route: 'staff', ...staff, staff_name: p.first_name } };
}

const BOOKING_LINK = 'https://example.com/book/piriye-1on1 (demo booking link)';
const reasons = [];
if (!crm.registered) reasons.push('no registered personal trading account');
if (crm.registered && !crm.kyc_verified) reasons.push('KYC verification not completed');
if (crm.ftd_amount <= 0) reasons.push('no confirmed first-time deposit');
if (crm.balance <= 0) reasons.push('personal account balance is 0 (unfunded)');
const eligible = reasons.length === 0;
const yn = (b) => (b ? 'YES' : 'NO');

const humanRe = /\b(speak|talk|chat|connect)\b.{0,25}\b(human|person|agent|manager|someone real|real person|sales ?rep|representative|staff|support team)\b|\b(live agent|real human|human agent)\b/i;
const seriousRe = /\b(scam(med)?|fraud|hacked|stolen|unauthori[sz]ed|lawyer|sue|suing|police|regulator|chargeback|report (you|exness))\b/i;
let hardTrigger = '';
if (seriousRe.test(p.text)) hardTrigger = 'Serious issue raised (fraud, security, legal or regulatory)';
else if (humanRe.test(p.text)) hardTrigger = 'Client explicitly asked for a human';

let route = 'agent';
if (/^\/demo\b/i.test(p.text)) route = 'demo';
else if (crm.escalated || crm.one_on_one_booked) route = 'frozen';

const trackGuide = {
  TRADING: 'BDM MODE only (Thread_Retail_Trading). Do not add IB/affiliate content.',
  IB: 'IB GROWTH MANAGER MODE only (Thread_Affiliate_IB). Do not add trading-account content unless asked. No signature.',
  MIXED: 'BOTH TRACKS. Answer in two clearly separated numbered sections: "1️⃣ YOUR TRADING ACCOUNT" then "2️⃣ YOUR IB BUSINESS". Keep each section strictly within its own thread data.',
  GENERAL: 'No specific track detected. If this is a greeting or /start, welcome them warmly and qualify them (new to trading? already have an Exness account? interested in the IB partner programme?). If they reply with a number or short answer, map it to the options you offered earlier. Otherwise use the most relevant track.'
}[p.track];

const prompt = [
  '[CLIENT MESSAGE]',
  p.text,
  '',
  '[ROUTING] Detected track: ' + p.track + ' -> ' + trackGuide,
  hardTrigger ? '[ESCALATION] HARD TRIGGER: ' + hardTrigger + '. You MUST escalate: write a short empathetic handoff reply and end with the [[ESCALATE: reason]] tag.' : '[ESCALATION] No hard trigger. Handle it yourself unless the escalation policy clearly applies.',
  crm.last_staff_note ? '[STAFF HANDOFF NOTE] A human member of Mr. Piriye\'s team recently took over this chat and their latest message to the client was: "' + crm.last_staff_note + '". The chat has been handed back to you. Continue naturally from what staff said, never contradict their commitments, and do not re-escalate for the same issue unless the client is still clearly unhappy.' : '',
  '',
  '[Thread_Retail_Trading - live CRM snapshot]',
  '- Registered personal account: ' + yn(crm.registered),
  '- KYC verified: ' + yn(crm.kyc_verified),
  '- First-time deposit: ' + crm.ftd_amount + ' USD',
  '- Current balance: ' + crm.balance + ' USD',
  '- Days since last trade: ' + crm.days_inactive + (crm.days_inactive >= 20 ? ' (DORMANT - use the reactivation approach if relevant)' : ''),
  '- 1-on-1 strategy session eligibility (validated against CRM just now): ' + (eligible ? 'ELIGIBLE' : 'NOT ELIGIBLE - ' + reasons.join('; ')),
  '- Booking link: ' + (eligible ? BOOKING_LINK : 'LOCKED. Do not share, invent or hint at any booking link or calendar.'),
  '',
  '[Thread_Affiliate_IB - live CRM snapshot]',
  '- IB partner: ' + yn(crm.is_ib),
  '- Verified referrals: ' + crm.ib_referrals + (crm.ib_referrals >= 10 ? ' (10+ MILESTONE REACHED - celebrate it)' : ''),
  '- Partner link: ' + (crm.ib_link || 'none yet'),
  '',
  '[CLIENT] First name: ' + p.first_name + ' | Today: ' + new Date().toISOString().slice(0, 10)
].filter((l, i, a) => l !== '' || a[i - 1] !== '').join('\n');

return { json: { ...p, crm, eligible, route, hard_trigger: hardTrigger, agent_prompt: prompt } };

const ctx = $input.item.json;
const s = { ...ctx.crm };
const parts = ctx.text.trim().split(/\s+/);
const cmd = (parts[1] || 'help').toLowerCase();
const num = Number(parts[2]);
let reply = '';
let showState = true;
const DEMO_LINK = 'https://one.exness.link/a/demo-ib-' + ctx.chat_id.slice(-5);
switch (cmd) {
  case 'register':
    s.registered = true; s.kyc_verified = true;
    reply = 'Demo CRM: account REGISTERED and KYC VERIFIED (unfunded).'; break;
  case 'fund': {
    const amt = Number.isFinite(num) && num > 0 ? num : 500;
    s.registered = true; s.kyc_verified = true; s.ftd_amount = s.ftd_amount > 0 ? s.ftd_amount : amt; s.balance = amt; s.days_inactive = 0;
    reply = 'Demo CRM: FTD confirmed, balance set to ' + amt + ' USD.'; break; }
  case 'unfund':
    s.balance = 0; reply = 'Demo CRM: balance set to 0 USD (unfunded).'; break;
  case 'ib': {
    const n = Number.isFinite(num) && num >= 0 ? num : 10;
    s.is_ib = true; s.ib_referrals = n; s.ib_link = s.ib_link || DEMO_LINK;
    reply = 'Demo CRM: IB partner ACTIVE with ' + n + ' verified referrals.'; break; }
  case 'dormant':
    s.registered = true; s.kyc_verified = true; s.ftd_amount = s.ftd_amount > 0 ? s.ftd_amount : 100; s.balance = 4; s.days_inactive = 25;
    reply = 'Demo CRM: account DORMANT (25 days inactive, balance 4 USD).'; break;
  case 'book':
    if (!ctx.eligible) { reply = 'Demo CRM: cannot book. The client is not eligible (personal account must be verified and funded). Try /demo fund 500 first.'; break; }
    s.one_on_one_booked = true;
    reply = 'Demo CRM: 1-on-1 BOOKED. Automation is now FROZEN for this chat and routed to Mr. Piriye. Send /demo resume to hand back to the AI.'; break;
  case 'escalate':
    s.escalated = true; s.escalation_reason = 'Manual escalation (demo)';
    reply = 'Demo CRM: chat ESCALATED to a live sales rep. AI replies paused. Send /demo resume to hand back to the AI.'; break;
  case 'resume':
  case 'unfreeze':
    s.one_on_one_booked = false; s.escalated = false; s.escalation_reason = '';
    reply = 'Demo CRM: automation RESUMED. Priye (AI) is handling this chat again.'; break;
  case 'reset':
    Object.assign(s, { registered: false, kyc_verified: false, ftd_amount: 0, balance: 0, days_inactive: 0, is_ib: false, ib_referrals: 0, ib_link: '', one_on_one_booked: false, escalated: false, escalation_reason: '', last_staff_note: '' });
    reply = 'Demo CRM: profile RESET to a brand-new lead.'; break;
  case 'status':
    reply = 'Demo CRM status:'; break;
  default:
    showState = false;
    reply = [
      'Demo controls (simulate the Exness CRM):',
      '/demo status - show this client record',
      '/demo register - registered + KYC, unfunded',
      '/demo fund 500 - confirm FTD and set balance',
      '/demo unfund - set balance to 0',
      '/demo ib 10 - make client an IB with N verified referrals',
      '/demo dormant - 25 days inactive, low balance',
      '/demo book - book the 1-on-1 (only if eligible) and pause the AI',
      '/demo escalate - hand the chat to a live sales rep',
      '/demo resume - hand the chat back to the AI',
      '/demo reset - back to a new lead',
      '',
      'Staff: reply to an escalation alert to answer the client (AI resumes automatically), or use /reply <chat_id> <message> or /resume <chat_id>.'
    ].join('\n');
}
const elig = s.registered && s.kyc_verified && s.ftd_amount > 0 && s.balance > 0;
if (showState) {
  reply += '\n\nRegistered: ' + s.registered + ' | KYC: ' + s.kyc_verified + ' | FTD: ' + s.ftd_amount + ' | Balance: ' + s.balance + ' | Days inactive: ' + s.days_inactive + '\nIB: ' + s.is_ib + ' | Referrals: ' + s.ib_referrals + ' | 1-on-1 eligible: ' + elig + ' | Booked: ' + s.one_on_one_booked + ' | Escalated: ' + s.escalated;
}
return { json: { chat_id: ctx.chat_id, ...s, reply } };

const ctxs = $('Build Context').all().filter(i => i.json.route === 'agent').map(i => i.json);
const out = [];
$input.all().forEach((item, idx) => {
  const ctx = ctxs[idx] || ctxs[0] || {};
  let raw = String(item.json.output || '');
  let escalate = false;
  let reason = '';
  const m = raw.match(/\[\[\s*ESCALATE\s*:?\s*([^\]]*)\]\]/i);
  if (m) { escalate = true; reason = (m[1] || '').trim(); raw = raw.replace(m[0], ''); }
  if (!escalate && ctx.hard_trigger) { escalate = true; reason = ctx.hard_trigger; }
  raw = raw.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#+\s*/gm, '').trim();
  const text = raw || ('Sorry ' + (ctx.first_name || 'there') + ', I hit a small hiccup just now. Could you send that again? If it keeps happening, Mr. Piriye\'s team will follow up shortly.');
  const chatId = item.json.chat_id || ctx.chat_id;
  if (chatId) out.push({ json: { chat_id: chatId, text: text.slice(0, 4000), escalate, escalation_reason: (reason || 'Conversation needs a human').slice(0, 300), first_name: ctx.first_name || '', client_message: ctx.text || '', track: ctx.track || '' } });
});
return out;
